const fs=require('node:fs'),readline=require('node:readline');let n=0;const send=x=>process.stdout.write(JSON.stringify(x)+'\n');readline.createInterface({input:process.stdin}).on('line',line=>{const m=JSON.parse(line),p=m.params||{};if(!m.method)return;const reply=result=>send({id:m.id,result});switch(m.method){case 'initialize':reply({});break;case 'account/read':reply({account:{type:'chatgpt'}});break;case 'model/list':reply({data:[{model:'fixture-codex',displayName:'本地模拟',isDefault:true,supportedReasoningEfforts:[{reasoningEffort:'low'},{reasoningEffort:'high'}],defaultReasoningEffort:'high'}]});break;case 'thread/start':if(process.env.CHAT_SPEED_LOG)fs.appendFileSync(process.env.CHAT_SPEED_LOG,JSON.stringify({instructions:p.developerInstructions})+'\n');reply({thread:{id:'thread-'+(++n)}});break;case 'turn/interrupt':reply({});send({method:'turn/completed',params:{threadId:p.threadId,turn:{id:p.turnId,status:'interrupted'}}});break;case 'turn/start':{const id='turn-'+(++n),threadId=p.threadId;reply({turn:{id}});send({method:'turn/started',params:{threadId,turn:{id}}});const input=JSON.parse(p.input[0].text.slice(p.input[0].text.indexOf('{')));if(process.env.CHAT_SPEED_LOG)fs.appendFileSync(process.env.CHAT_SPEED_LOG,JSON.stringify({pages:input.pages,images:p.input.filter(x=>x.type==='image').length})+'\n');const text=JSON.stringify(input.pages.map(page=>({page,keep:![4,5].includes(page),reason:page===4?'播放器画面':'课件页面',description:'合成测试第 '+page+' 页',contentScore:page===1?25:page===13?100:90,duplicateOf:page===1||page===13?2:null})));setTimeout(()=>{send({method:'item/completed',params:{threadId,item:{type:'agentMessage',phase:'final_answer',text}}});send({method:'turn/completed',params:{threadId,turn:{id,status:'completed'}}})},500);break}}});
